-- ---------------------------------------------------------------------------
-- Quiz des modules pilotes (livraison Big Five du 20/10)
--
-- FICHIER GÉNÉRÉ : ne pas éditer à la main.
-- Régénération : npm run quiz:importer
-- Application  : npm run db:appliquer -- supabase/rattrapage-quiz-pilotes.sql
--
-- Rejouable : quiz mis à jour en place, questions remplacées, tentatives des
-- apprenants conservées. Exige la migration 40 (quiz_modules).
-- ---------------------------------------------------------------------------

begin;

-- ENT_M04 → mod-trouver-ses-premiers-clients
insert into quiz (module_id, code, version, seuil_reussite, tentatives_par_jour)
values ('mod-trouver-ses-premiers-clients', 'ENT_M04', 'v1', 100, 3)
on conflict (module_id) do update
  set code = excluded.code, version = excluded.version,
      seuil_reussite = excluded.seuil_reussite, tentatives_par_jour = excluded.tentatives_par_jour;
delete from quiz_questions where module_id = 'mod-trouver-ses-premiers-clients';
insert into quiz_questions
  (module_id, position, code, niveau, competence, enonce, options, bonne_reponse, justification, piste_si_erreur, renvois)
values
  ('mod-trouver-ses-premiers-clients', 1, 'Q01', 'application', 'Dépasser le piège de l''attente',
   'Aïcha prépare des jus naturels que ses proches adorent. Avant de vendre, elle veut un logo professionnel et au moins 5 000 abonnés sur sa page. Selon le formateur, que doit-elle faire ?',
   '[{"id":"A","texte":"Faire d''abord réaliser son logo, car c''est lui qui rassure les premiers clients."},{"id":"B","texte":"Attendre ses 5 000 abonnés pour lancer ses ventes au bon moment."},{"id":"C","texte":"Commencer à vendre dès maintenant, puisque son produit fonctionne, et l''améliorer en avançant."},{"id":"D","texte":"Créer d''abord un site internet complet pour donner une image sérieuse."}]'::jsonb,
   'C', 'Le formateur insiste : il n''y a jamais de bon moment et la perfection n''est pas un préalable. Dès que le produit fonctionne, c''est suffisant pour démarrer ; logo, page et site se construisent ensuite. Attendre d''être « prêt » donne toujours une bonne raison de repousser.', 'Repensez à ce que dit le formateur sur le « bon moment » pour se lancer et sur ce qui suffit réellement pour démarrer une activité.',
   '[{"position":1,"titre":"Introduction","debut_s":64.5,"libelle":"Revoir le chapitre 1 : « Introduction » (vers 01:04)"}]'::jsonb),
  ('mod-trouver-ses-premiers-clients', 2, 'Q02', 'compréhension', 'Reconnaître une offre',
   'Au sens où le formateur définit une offre, laquelle de ces publications présente réellement une offre ?',
   '[{"id":"A","texte":"« Nos pagnes wax sont les plus beaux d''Abidjan, venez voir nos collections. »"},{"id":"B","texte":"« Pagne wax 6 yards à 15 000 FCFA. Pour commander, écrivez-nous sur WhatsApp au numéro ci-dessous. »"},{"id":"C","texte":"« Spécialistes du wax depuis dix ans, nous sommes à votre service. »"},{"id":"D","texte":"« Découvrez notre nouvelle collection de pagnes, disponible très bientôt. »"}]'::jsonb,
   'B', 'Pour le formateur, une offre, c''est un produit, un prix et la manière de l''obtenir (« iPhone 15 Pro à 500 000 ; pour l''avoir, contactez tel numéro »). Seule la proposition B réunit les trois éléments ; les autres présentent l''entreprise ou le produit sans prix ni moyen de commander.', 'Rappelez-vous les trois éléments qui, selon le formateur, composent une offre, puis vérifiez lesquels sont présents dans chaque publication.',
   '[{"position":2,"titre":"Définitions","debut_s":12.7,"libelle":"Revoir le chapitre 2 : « Définitions » (vers 00:12)"}]'::jsonb),
  ('mod-trouver-ses-premiers-clients', 3, 'Q03', 'application', 'Identifier un frein à l''achat',
   'Un prospect trouve votre produit intéressant mais répond : « C''est bien, je reviendrai le mois prochain. » D''après le formateur, quel frein se cache derrière cette réponse et comment votre offre doit-elle y répondre ?',
   '[{"id":"A","texte":"Il sait que votre produit peut attendre : votre offre doit créer de l''urgence."},{"id":"B","texte":"Il trouve votre produit mauvais : vous devez d''abord améliorer sa qualité."},{"id":"C","texte":"Il ne fait pas partie de votre cible : vous devez chercher d''autres prospects."},{"id":"D","texte":"Il manque d''options : vous devez lui envoyer votre catalogue complet."}]'::jsonb,
   'A', 'Le formateur explique que l''argent des gens ne suffit pas : s''ils savent que votre produit peut attendre, ils achètent d''abord ce qui est urgent. Une offre de lancement limitée dans la durée (ou en quantité) pousse à décider aujourd''hui plutôt que demain.', 'Demandez-vous ce que fait un client au budget limité lorsqu''il sait qu''un achat peut être repoussé, et ce que l''offre de lancement doit ajouter pour l''en empêcher.',
   '[{"position":3,"titre":"Construire une offre de lancement qui donne envie","debut_s":101,"libelle":"Revoir le chapitre 3 : « Construire une offre de lancement qui donne envie » (vers 01:40)"}]'::jsonb),
  ('mod-trouver-ses-premiers-clients', 4, 'Q04', 'application', 'Rendre l''offre actionnable',
   'Koffi publie une belle vidéo de ses chaussures en cuir, avec des avis de clients satisfaits. Beaucoup de personnes regardent, mais personne ne commande. Selon le formateur, quelle est la cause la plus probable ?',
   '[{"id":"A","texte":"Sa vidéo est trop courte pour convaincre."},{"id":"B","texte":"Il n''a pas assez publié de témoignages clients."},{"id":"C","texte":"Ses chaussures ne correspondent pas aux besoins du marché."},{"id":"D","texte":"Il n''indique ni le prix ni une manière simple de commander."}]'::jsonb,
   'D', 'Le formateur cite précisément ce cas : on regarde la publication, on est intéressé, mais on ne sait pas combien ça coûte ni comment commander, alors on passe son chemin. Une offre efficace indique le prix et un moyen de commander « en un seul geste » (un message, un appel, un lien).', 'Mettez-vous à la place de la personne intéressée par la vidéo : de quelles informations a-t-elle besoin pour passer à l''action ?',
   '[{"position":3,"titre":"Construire une offre de lancement qui donne envie","debut_s":203.1,"libelle":"Revoir le chapitre 3 : « Construire une offre de lancement qui donne envie » (vers 03:23)"},{"position":3,"titre":"Construire une offre de lancement qui donne envie","debut_s":746.8,"libelle":"Revoir le chapitre 3 : « Construire une offre de lancement qui donne envie » (vers 12:26)"}]'::jsonb),
  ('mod-trouver-ses-premiers-clients', 5, 'Q05', 'application', 'Simplifier son offre de lancement',
   'Mariam ouvre un maquis et propose 25 plats différents pour satisfaire toutes les demandes. Son argent est immobilisé dans les ingrédients et personne ne la connaît pour une spécialité. Que lui conseillerait le formateur ?',
   '[{"id":"A","texte":"Ajouter encore des plats pour ne jamais refuser un client."},{"id":"B","texte":"Réduire sa carte au plat dans lequel elle excelle et se faire connaître pour lui."},{"id":"C","texte":"Baisser le prix de tous ses plats pour attirer plus de monde."},{"id":"D","texte":"Garder sa carte mais investir dans la publicité payante."}]'::jsonb,
   'B', 'C''est l''exemple de la restauratrice accompagnée par le formateur : il a réduit sa carte au porc, ce qu''elle faisait le mieux. Une offre simple positionne et marque les esprits ; on pourra ajouter d''autres produits au fur et à mesure.', 'Souvenez-vous de l''exemple de la restauratrice accompagnée par le formateur et de ce qu''il a changé dans sa manière de se présenter au marché.',
   '[{"position":3,"titre":"Construire une offre de lancement qui donne envie","debut_s":397.6,"libelle":"Revoir le chapitre 3 : « Construire une offre de lancement qui donne envie » (vers 06:37)"}]'::jsonb),
  ('mod-trouver-ses-premiers-clients', 6, 'Q06', 'compréhension', 'Fixer un prix accessible',
   'Pour le formateur, que signifie un prix « accessible » dans une offre de lancement ?',
   '[{"id":"A","texte":"Le prix le plus bas du marché, quitte à ne faire aucune marge au début."},{"id":"B","texte":"Un prix élevé, pour donner une image haut de gamme dès le lancement."},{"id":"C","texte":"Un prix facile à accepter par le client, qui permet tout de même de gagner de l''argent."},{"id":"D","texte":"Un prix qui change selon chaque client, en fonction de sa capacité à payer."}]'::jsonb,
   'C', 'Le formateur précise qu''accessible ne veut pas dire baisser le prix jusqu''à ce qu''il soit dérisoire (« autant faire zéro franc »). Le prix doit être facile à accepter tout en permettant de faire de l''argent, puisque l''objectif est de construire un business rentable.', 'Le formateur rappelle que l''objectif reste de construire un business qui rapporte : interrogez-vous sur ce que le prix doit permettre, côté client comme côté vendeur.',
   '[{"position":3,"titre":"Construire une offre de lancement qui donne envie","debut_s":461.1,"libelle":"Revoir le chapitre 3 : « Construire une offre de lancement qui donne envie » (vers 07:41)"}]'::jsonb),
  ('mod-trouver-ses-premiers-clients', 7, 'Q07', 'application', 'Évaluer une offre de lancement',
   'Parmi ces quatre annonces pour un savon artisanal, laquelle réunit le mieux les caractéristiques d''une offre de lancement efficace selon le formateur ?',
   '[{"id":"A","texte":"« Savons artisanaux de qualité, plusieurs parfums disponibles. Contactez-moi pour avoir plus d''informations. »"},{"id":"B","texte":"« Savons disponibles à tous les prix pour toute la famille. Écrivez-moi en privé pour recevoir les infos. »"},{"id":"C","texte":"« Découvrez notre gamme complète de savons, gels et crèmes au karité : il y en a pour tous les goûts. »"},{"id":"D","texte":"« Savon au karité 100 % naturel, lot de 3 à 2 500 FCFA. Livraison offerte aux 20 premières commandes cette semaine. Écrivez SAVON en privé. »"}]'::jsonb,
   'D', 'Comme pour l''exercice des gâteaux, l''offre D est claire et précise (produit, bénéfice, prix), accessible, limitée (20 premières commandes, cette semaine) avec un bonus, et indique comment commander en un geste. Les autres sont vagues ou proposent un catalogue, ce que le formateur déconseille au lancement.', 'Reprenez la liste des caractéristiques d''une offre efficace (clarté, simplicité, prix, limite, bonus, manière de commander) et vérifiez quelle annonce les réunit.',
   '[{"position":3,"titre":"Construire une offre de lancement qui donne envie","debut_s":237.4,"libelle":"Revoir le chapitre 3 : « Construire une offre de lancement qui donne envie » (vers 03:57)"},{"position":3,"titre":"Construire une offre de lancement qui donne envie","debut_s":992.1,"libelle":"Revoir le chapitre 3 : « Construire une offre de lancement qui donne envie » (vers 16:32)"}]'::jsonb),
  ('mod-trouver-ses-premiers-clients', 8, 'Q08', 'application', 'Activer son réseau sans le braquer',
   'Serge lance son activité de traiteur et veut prévenir ses contacts. Quelle démarche est conforme aux conseils du formateur ?',
   '[{"id":"A","texte":"Écrire à chacun individuellement, prendre de ses nouvelles, puis présenter son offre et demander une recommandation."},{"id":"B","texte":"Créer un groupe WhatsApp, y ajouter tous ses contacts sans leur demander et y partager ses flyers chaque jour."},{"id":"C","texte":"Envoyer le même message de présentation, avec son menu et ses prix, à ses 500 contacts en une seule fois."},{"id":"D","texte":"Relancer chaque jour ceux qui n''ont pas répondu à son message, jusqu''à obtenir une réponse claire."}]'::jsonb,
   'A', 'Le formateur recommande d''écrire aux gens un à un, de façon personnalisée, en reprenant contact avant de parler de son activité. Il met en garde contre le spam, les groupes créés sans consentement et le harcèlement de ceux qui ne répondent pas, qui provoquent l''effet contraire.', 'Revoyez ce qu''il faut faire et ce qu''il faut éviter avec son réseau personnel, en particulier sur WhatsApp.',
   '[{"position":4,"titre":"Vendre sans budget : réseau et canaux rapides","debut_s":250.6,"libelle":"Revoir le chapitre 4 : « Vendre sans budget : réseau et canaux rapides » (vers 04:10)"},{"position":4,"titre":"Vendre sans budget : réseau et canaux rapides","debut_s":115.5,"libelle":"Revoir le chapitre 4 : « Vendre sans budget : réseau et canaux rapides » (vers 01:55)"}]'::jsonb),
  ('mod-trouver-ses-premiers-clients', 9, 'Q09', 'application', 'Appliquer la méthode V.E.N.T.E.',
   'Vous voulez parler de votre nouvelle activité à une ancienne camarade de classe. Quel enchaînement respecte la méthode V.E.N.T.E. présentée par le formateur ?',
   '[{"id":"A","texte":"Lui envoyer directement votre offre de lancement, attendre sa réponse, puis prendre de ses nouvelles pour garder le lien."},{"id":"B","texte":"Lui demander d''abord une recommandation, puis lui présenter votre activité et votre offre, et la relancer chaque semaine."},{"id":"C","texte":"La choisir dans votre liste de cibles, reprendre contact, présenter votre activité, partager l''offre, puis demander une recommandation."},{"id":"D","texte":"Lui présenter votre activité et votre offre dès le premier message, puis reprendre contact plus tard pour avoir son avis."}]'::jsonb,
   'C', 'La méthode V.E.N.T.E. suit un ordre précis : Viser (lister les personnes susceptibles d''acheter), Échanger (reprendre contact sans vendre), Nommer (présenter son activité), Transmettre (partager l''offre) et Élargir (demander une recommandation si la personne n''est pas intéressée).', 'Reprenez chaque lettre du sigle dans l''ordre et l''action qu''elle désigne, de la sélection des personnes jusqu''à la dernière étape.',
   '[{"position":4,"titre":"Vendre sans budget : réseau et canaux rapides","debut_s":498.6,"libelle":"Revoir le chapitre 4 : « Vendre sans budget : réseau et canaux rapides » (vers 08:18)"}]'::jsonb),
  ('mod-trouver-ses-premiers-clients', 10, 'Q10', 'application', 'Gérer les refus',
   'Sur ses dix premiers messages de prospection, Fatou reçoit neuf refus. D''après le formateur, quelle est la bonne façon de réagir ?',
   '[{"id":"A","texte":"Conclure que son offre ne fonctionne pas et la remplacer immédiatement par une autre."},{"id":"B","texte":"Considérer ces « non » comme normaux, continuer régulièrement et améliorer sa technique."},{"id":"C","texte":"Baisser ses prix tout de suite pour transformer ces refus en ventes."},{"id":"D","texte":"Relancer chaque jour les neuf personnes jusqu''à ce qu''elles finissent par acheter."}]'::jsonb,
   'B', 'Pour le formateur, la vente est une affaire de taux de conversion : la majorité des gens diront non, et c''est normal. Chaque « non » rapproche de celui qui va acheter. Il conseille la régularité (quelques contacts par jour plutôt que 50 en une fois) et l''analyse de chaque échange pour s''améliorer.', 'Rappelez-vous ce que le formateur dit du taux de conversion, de la régularité et de l''attitude à adopter face aux refus.',
   '[{"position":4,"titre":"Vendre sans budget : réseau et canaux rapides","debut_s":765.8,"libelle":"Revoir le chapitre 4 : « Vendre sans budget : réseau et canaux rapides » (vers 12:45)"},{"position":4,"titre":"Vendre sans budget : réseau et canaux rapides","debut_s":891.7,"libelle":"Revoir le chapitre 4 : « Vendre sans budget : réseau et canaux rapides » (vers 14:51)"}]'::jsonb);

-- ENT_M05 → mod-vendre-sans-site-web-whatsapp-business
insert into quiz (module_id, code, version, seuil_reussite, tentatives_par_jour)
values ('mod-vendre-sans-site-web-whatsapp-business', 'ENT_M05', 'v1', 100, 3)
on conflict (module_id) do update
  set code = excluded.code, version = excluded.version,
      seuil_reussite = excluded.seuil_reussite, tentatives_par_jour = excluded.tentatives_par_jour;
delete from quiz_questions where module_id = 'mod-vendre-sans-site-web-whatsapp-business';
insert into quiz_questions
  (module_id, position, code, niveau, competence, enonce, options, bonne_reponse, justification, piste_si_erreur, renvois)
values
  ('mod-vendre-sans-site-web-whatsapp-business', 1, 'Q01', 'application', 'Ne pas donner le prix trop tôt',
   'Un prospect vous écrit sur WhatsApp : « Bonjour, j''ai vu vos boubous marocains, c''est combien ? » D''après le formateur, quelle est la meilleure première réponse ?',
   '[{"id":"A","texte":"« Bonjour, ils sont à 35 000 FCFA. Vous en voulez combien ? »"},{"id":"B","texte":"« Bonjour, merci pour votre message. C''est pour quelle occasion, et quel type de boubou vous intéresse ? »"},{"id":"C","texte":"« Bonjour, voici notre catalogue complet avec tous nos modèles et leurs prix. »"},{"id":"D","texte":"« Bonjour, pour vous, je fais une remise immédiate : 25 000 FCFA au lieu de 35 000. »"}]'::jsonb,
   'B', 'Le formateur explique que le client compare tout de suite le prix à la valeur perçue qu''il a en tête : si elle est inférieure, il dira que c''est cher. Il faut d''abord accueillir, remercier et poser des questions de découverte pour comprendre le vrai besoin, avant de proposer l''offre adaptée et son prix.', 'Rappelez-vous ce que fait le client dans sa tête dès qu''il entend un prix, et ce que le formateur recommande de faire avant de l''annoncer.',
   '[{"position":3,"titre":"Vendre en conversation : les scripts qui convertissent","debut_s":363.1,"libelle":"Revoir le chapitre 3 : « Vendre en conversation : les scripts qui convertissent » (vers 06:03)"}]'::jsonb),
  ('mod-vendre-sans-site-web-whatsapp-business', 2, 'Q02', 'compréhension', 'Reformuler le besoin',
   'Selon le formateur, pourquoi faut-il reformuler le besoin du prospect avant de présenter son offre ?',
   '[{"id":"A","texte":"Pour gagner du temps en évitant de poser d''autres questions."},{"id":"B","texte":"Pour montrer au prospect que l''on maîtrise le vocabulaire technique du produit."},{"id":"C","texte":"Pour obliger le prospect à répéter sa demande et le pousser à se décider plus vite."},{"id":"D","texte":"Pour vérifier qu''on a bien compris et que le prospect voie la solution proposée comme la bonne."}]'::jsonb,
   'D', 'La reformulation permet de s''assurer qu''on a compris le besoin. Quand le prospect se dit « il a vraiment compris ce que je veux », il considère, de façon inconsciente, que la solution qu''on va lui proposer est forcément la bonne.', 'Pensez à l''effet que produit la reformulation dans la tête du prospect, d''après l''exemple du boubou porté à la maison.',
   '[{"position":3,"titre":"Vendre en conversation : les scripts qui convertissent","debut_s":483.2,"libelle":"Revoir le chapitre 3 : « Vendre en conversation : les scripts qui convertissent » (vers 08:03)"}]'::jsonb),
  ('mod-vendre-sans-site-web-whatsapp-business', 3, 'Q03', 'application', 'Conclure avec une question fermée',
   'Votre prospect est convaincu par le produit et vous dit : « OK, d''accord. » Quelle question vous aide le mieux à conclure la vente, selon le formateur ?',
   '[{"id":"A","texte":"« Préférez-vous être livré aujourd''hui ou passer le récupérer demain ? »"},{"id":"B","texte":"« Quand est-ce que vous souhaitez être livré, à votre convenance ? »"},{"id":"C","texte":"« Très bien, faites-moi signe quand vous serez prêt à commander. »"},{"id":"D","texte":"« Avez-vous encore des questions sur le produit avant de réfléchir ? »"}]'::jsonb,
   'A', 'Le formateur met en garde contre l''erreur de laisser la décision dans la main du prospect. À la fin, il faut des questions fermées qui obligent à faire un choix (livraison ou retrait, aujourd''hui ou demain, espèces ou mobile money) : plus le client fait de choix, plus on avance vers la conclusion.', 'Demandez-vous quelle formulation laisse le prospect repousser sa décision, et laquelle l''amène à faire un choix concret.',
   '[{"position":3,"titre":"Vendre en conversation : les scripts qui convertissent","debut_s":963.3,"libelle":"Revoir le chapitre 3 : « Vendre en conversation : les scripts qui convertissent » (vers 16:03)"}]'::jsonb),
  ('mod-vendre-sans-site-web-whatsapp-business', 4, 'Q04', 'application', 'Accueillir l''objection « c''est cher »',
   'Vous proposez un ensemble à 30 000 FCFA et la cliente répond : « C''est cher. » Quelle est la première chose à faire, d''après le formateur ?',
   '[{"id":"A","texte":"Baisser tout de suite à 25 000 FCFA pour ne pas la perdre."},{"id":"B","texte":"Lui expliquer que les autres vendeurs sont bien plus chers que vous."},{"id":"C","texte":"Lui demander pourquoi elle trouve que c''est cher, pour comprendre le vrai frein."},{"id":"D","texte":"La remercier et passer à une autre cliente plus intéressée."}]'::jsonb,
   'C', 'Pour le formateur, il ne faut ni baisser son prix dès la première hésitation ni argumenter pour avoir raison. La simple question « pourquoi pensez-vous que c''est cher ? » révèle souvent le vrai frein, par exemple un budget prévu de 10 000 FCFA seulement.', 'Repensez aux erreurs que le formateur liste face à une objection, puis à ce qu''il conseille de faire en premier pour comprendre la situation.',
   '[{"position":4,"titre":"Objections et relances : conclure sans harceler","debut_s":247.4,"libelle":"Revoir le chapitre 4 : « Objections et relances : conclure sans harceler » (vers 04:07)"}]'::jsonb),
  ('mod-vendre-sans-site-web-whatsapp-business', 5, 'Q05', 'application', 'Rehausser la valeur perçue',
   'Un client veut une tenue pour le mariage d''amis proches, mais il avait prévu 10 000 FCFA et votre modèle coûte 30 000 FCFA. Quelle démarche suit les conseils du formateur ?',
   '[{"id":"A","texte":"Lui accorder directement le prix de 10 000 FCFA pour ne pas perdre la vente et conclure rapidement."},{"id":"B","texte":"Montrer que ce modèle répond à l''importance du mariage, donner des preuves, puis proposer une alternative si besoin."},{"id":"C","texte":"Lui dire franchement que ce produit n''est pas fait pour son budget et lui conseiller d''aller voir ailleurs."},{"id":"D","texte":"Insister à plusieurs reprises jusqu''à ce qu''il accepte de trouver l''argent manquant pour le mariage."}]'::jsonb,
   'B', 'Le formateur cherche d''abord à augmenter la valeur perçue (honorer le couple, qualité adaptée à l''occasion) et à la renforcer par des preuves (photo d''un client satisfait). Si le budget ne peut vraiment pas évoluer, il propose une alternative : paiement fractionné ou autre produit dans son budget.', 'Rappelez-vous l''exemple du mariage : le formateur ne touche pas d''abord au prix. Que cherche-t-il à faire évoluer, et dans quel ordre ?',
   '[{"position":4,"titre":"Objections et relances : conclure sans harceler","debut_s":368.7,"libelle":"Revoir le chapitre 4 : « Objections et relances : conclure sans harceler » (vers 06:08)"},{"position":4,"titre":"Objections et relances : conclure sans harceler","debut_s":400.4,"libelle":"Revoir le chapitre 4 : « Objections et relances : conclure sans harceler » (vers 06:40)"}]'::jsonb),
  ('mod-vendre-sans-site-web-whatsapp-business', 6, 'Q06', 'application', 'Faire émerger toutes les objections',
   'Un prospect vous dit : « C''est cher… et puis je ne suis pas sûr que ça m''aille. » Comment le formateur recommande-t-il de procéder ?',
   '[{"id":"A","texte":"Répondre immédiatement à la première objection, puis à la seconde."},{"id":"B","texte":"Ignorer la deuxième remarque, qui n''est qu''un prétexte."},{"id":"C","texte":"Traiter seulement l''objection la plus facile pour avancer."},{"id":"D","texte":"Lui demander s''il y a un autre point bloquant avant de répondre à tout."}]'::jsonb,
   'D', 'Le formateur conseille de ne pas traiter chaque objection individuellement : il faut d''abord écouter et creuser pour que le prospect émette toutes ses objections (« Est-ce qu''il y a un autre point bloquant ? »), puis rassurer sur l''ensemble.', 'Revoyez la méthode de gestion des objections et ce qu''il faut faire quand le prospect en exprime plusieurs.',
   '[{"position":4,"titre":"Objections et relances : conclure sans harceler","debut_s":547,"libelle":"Revoir le chapitre 4 : « Objections et relances : conclure sans harceler » (vers 09:07)"}]'::jsonb),
  ('mod-vendre-sans-site-web-whatsapp-business', 7, 'Q07', 'application', 'Relancer sans harceler',
   'Lundi, une prospecte vous a dit : « Je vais réfléchir. » Quel plan de relance est conforme à celui du formateur ?',
   '[{"id":"A","texte":"Mardi, un rappel léger avec une info utile ; jeudi, un témoignage ; lundi suivant, une dernière relance limitée dans le temps."},{"id":"B","texte":"Une relance chaque matin, par message puis par appel, jusqu''à ce qu''elle donne une réponse définitive."},{"id":"C","texte":"Ne plus la contacter et attendre qu''elle revienne d''elle-même vers vous quand elle sera décidée."},{"id":"D","texte":"Une seule relance, un mois plus tard, pour être sûr de ne pas la déranger pendant sa réflexion."}]'::jsonb,
   'A', 'Le plan du formateur se fait en trois étapes : à J+1, un rappel léger avec une information utile (un bonus) ; deux jours après, un retour d''expérience client ; à J+7, une dernière relance avec une limite de durée. Ensuite, on laisse et on se concentre sur d''autres prospects, sans harceler.', 'Rappelez-vous le plan en trois étapes présenté par le formateur et la règle qu''il donne pour ne pas harceler.',
   '[{"position":4,"titre":"Objections et relances : conclure sans harceler","debut_s":866.9,"libelle":"Revoir le chapitre 4 : « Objections et relances : conclure sans harceler » (vers 14:26)"},{"position":4,"titre":"Objections et relances : conclure sans harceler","debut_s":895.6,"libelle":"Revoir le chapitre 4 : « Objections et relances : conclure sans harceler » (vers 14:55)"}]'::jsonb),
  ('mod-vendre-sans-site-web-whatsapp-business', 8, 'Q08', 'compréhension', 'Comprendre ce qu''est une objection',
   'D''après le formateur, que signifie le plus souvent une objection comme « je vais réfléchir » ou « je dois demander l''avis de mon épouse » ?',
   '[{"id":"A","texte":"Un refus poli : le prospect n''achètera pas."},{"id":"B","texte":"Une manœuvre pour obtenir une baisse de prix."},{"id":"C","texte":"Une demande d''être rassuré, signe que la vente se rapproche."},{"id":"D","texte":"Un manque d''intérêt réel pour le produit proposé."}]'::jsonb,
   'C', 'Le formateur insiste : une objection n''est pas un refus, c''est une demande d''information pour être rassuré. Ce sont des indicateurs que l''on se rapproche de la vente ; il faut donc les gérer plutôt que s''en agacer.', 'Revoyez la définition des objections donnée au début du module et ce que le formateur dit de leur rôle dans la conversation de vente.',
   '[{"position":2,"titre":"Définitions","debut_s":95.3,"libelle":"Revoir le chapitre 2 : « Définitions » (vers 01:35)"},{"position":4,"titre":"Objections et relances : conclure sans harceler","debut_s":3,"libelle":"Revoir le chapitre 4 : « Objections et relances : conclure sans harceler » (vers 00:03)"}]'::jsonb),
  ('mod-vendre-sans-site-web-whatsapp-business', 9, 'Q09', 'application', 'Écouter avant de vendre',
   'Pendant dix minutes, Ibrahim présente toutes les qualités de son produit à un prospect, sans lui poser une seule question. Le prospect finit par partir. D''après le formateur, quelle est l''erreur principale ?',
   '[{"id":"A","texte":"Il n''a pas présenté assez de détails techniques sur son produit."},{"id":"B","texte":"Il n''a pas donné son prix assez tôt dans la conversation."},{"id":"C","texte":"Il n''a pas envoyé assez de photos et de vidéos au prospect."},{"id":"D","texte":"Il a parlé au lieu de faire parler le prospect pour comprendre son besoin."}]'::jsonb,
   'D', 'Pour le formateur, il faut que ce soit le prospect qui parle plus que le vendeur : en le faisant parler, on obtient ce qu''il veut, ce qui le freine et les arguments pour le convaincre. Plus le vendeur parle et moins le prospect se sent compris, plus la vente risque d''échouer.', 'Rappelez-vous la première caractéristique d''une conversation qui vend et qui, du vendeur ou du prospect, doit parler le plus.',
   '[{"position":3,"titre":"Vendre en conversation : les scripts qui convertissent","debut_s":121.4,"libelle":"Revoir le chapitre 3 : « Vendre en conversation : les scripts qui convertissent » (vers 02:01)"}]'::jsonb),
  ('mod-vendre-sans-site-web-whatsapp-business', 10, 'Q10', 'application', 'Ne pas prendre l''objection personnellement',
   'Adjoua fabrique elle-même ses savons. Quand une cliente doute de leur efficacité, elle se vexe et répond sèchement. Que lui conseillerait le formateur ?',
   '[{"id":"A","texte":"Défendre fermement la qualité de ses savons et argumenter jusqu''à avoir le dernier mot."},{"id":"B","texte":"Se détacher émotionnellement et rassurer la cliente, qui veut seulement bien dépenser son argent."},{"id":"C","texte":"Refuser poliment de vendre aux clientes qui se montrent méfiantes envers ses produits."},{"id":"D","texte":"Proposer tout de suite une réduction importante pour clore la discussion sans perdre la vente."}]'::jsonb,
   'B', 'Le formateur parle des entrepreneurs qui fabriquent leurs produits et prennent les questions comme une attaque personnelle. Il conseille de se détacher émotionnellement : le client donne un argent durement gagné et a besoin de s''assurer qu''il fait un bon investissement. La vente n''est pas un débat.', 'Repensez à ce que le formateur dit des entrepreneurs très attachés à leurs produits et à la raison pour laquelle les clients posent des questions.',
   '[{"position":4,"titre":"Objections et relances : conclure sans harceler","debut_s":196.9,"libelle":"Revoir le chapitre 4 : « Objections et relances : conclure sans harceler » (vers 03:16)"}]'::jsonb);

-- ENT_M08 → mod-contenus-qui-attirent-des-clients
insert into quiz (module_id, code, version, seuil_reussite, tentatives_par_jour)
values ('mod-contenus-qui-attirent-des-clients', 'ENT_M08', 'v1', 100, 3)
on conflict (module_id) do update
  set code = excluded.code, version = excluded.version,
      seuil_reussite = excluded.seuil_reussite, tentatives_par_jour = excluded.tentatives_par_jour;
delete from quiz_questions where module_id = 'mod-contenus-qui-attirent-des-clients';
insert into quiz_questions
  (module_id, position, code, niveau, competence, enonce, options, bonne_reponse, justification, piste_si_erreur, renvois)
values
  ('mod-contenus-qui-attirent-des-clients', 1, 'Q01', 'application', 'Commencer par ce que vit le client',
   'Adjoua vend des crèmes au karité à Cocody. Sa publication « Bienvenue chez Adjoua Beauté. Nous proposons des soins de qualité à des prix abordables. Contactez-nous. » obtient très peu de réactions. Quelle nouvelle accroche suit le conseil du formateur ?',
   '[{"id":"A","texte":"« Adjoua Beauté, la marque de soins naturels préférée des femmes d''Abidjan depuis 2020. »"},{"id":"B","texte":"« Votre peau tiraille malgré vos crèmes ? Trois erreurs gâchent votre routine. »"},{"id":"C","texte":"« Nouveau chez Adjoua Beauté : crème au karité à 5 000 FCFA, contactez-nous vite. »"},{"id":"D","texte":"« Découvrez notre équipe passionnée et nos soins de qualité à des prix abordables. »"}]'::jsonb,
   'B', 'Le formateur compare deux versions d''un même post de cosmétiques : celle qui présente l''entreprise ne crée aucune raison de s''arrêter, alors que celle qui démarre par une situation vécue par le client crée l''identification et ouvre la porte à une solution. Il faut commencer par ce que vit le client, pas par ce que l''on vend.', 'Demandez-vous par quoi le formateur conseille d''ouvrir un message pour que le lecteur s''y reconnaisse et ait une raison de s''arrêter de défiler.',
   '[{"position":2,"titre":"C''est quoi un contenu qui attire ?","debut_s":525.8,"libelle":"Revoir le chapitre 2 : « C''est quoi un contenu qui attire ? » (vers 08:45)"},{"position":2,"titre":"C''est quoi un contenu qui attire ?","debut_s":551,"libelle":"Revoir le chapitre 2 : « C''est quoi un contenu qui attire ? » (vers 09:11)"}]'::jsonb),
  ('mod-contenus-qui-attirent-des-clients', 2, 'Q02', 'application', 'Alterner les piliers de contenu',
   'Kouamé vend des chaussures à Adjamé. Chaque jour, sa page publie « Promo ! Achetez ! Contactez-nous ! ». Ses abonnés réagissent de moins en moins. Que lui conseillerait le formateur ?',
   '[{"id":"A","texte":"Publier ses promotions deux fois par jour pour rester visible auprès de ses abonnés."},{"id":"B","texte":"Remplacer ses promotions par des vidéos humoristiques pour devenir viral rapidement."},{"id":"C","texte":"Arrêter de publier quelques semaines pour que ses abonnés aient envie de revenir."},{"id":"D","texte":"Alterner conseils, questions, témoignages et offres selon les piliers de contenu."}]'::jsonb,
   'D', 'Pour le formateur, une page qui ne dit que « achetez, promotion, contactez-nous » finit par fatiguer l''audience. Il recommande d''alterner les quatre piliers : éducatif (conseils), engageant (questions, défis), inspirant (témoignages, storytelling) et promotionnel. Un contenu attractif n''a pas besoin d''être humoristique ou viral.', 'Repensez à ce qui, selon le formateur, fatigue une audience, et aux différents types de publications qu''il propose de faire tourner sur une page.',
   '[{"position":2,"titre":"C''est quoi un contenu qui attire ?","debut_s":577,"libelle":"Revoir le chapitre 2 : « C''est quoi un contenu qui attire ? » (vers 09:37)"},{"position":2,"titre":"C''est quoi un contenu qui attire ?","debut_s":595.5,"libelle":"Revoir le chapitre 2 : « C''est quoi un contenu qui attire ? » (vers 09:55)"}]'::jsonb),
  ('mod-contenus-qui-attirent-des-clients', 3, 'Q03', 'application', 'S''engager avec ceux qui réagissent',
   'Awa, coiffeuse à Yopougon, publie : « Quelle coiffure vous tente cette semaine : A ou B ? ». Une trentaine de personnes répondent en commentaire. Selon le formateur, que doit-elle faire ?',
   '[{"id":"A","texte":"Répondre vite à chaque commentaire et relancer la discussion par une question."},{"id":"B","texte":"Remercier tout le monde par un seul commentaire général, puis passer à autre chose."},{"id":"C","texte":"Laisser les commentaires sans réponse pour ne pas paraître trop disponible."},{"id":"D","texte":"Supprimer la publication et la republier le lendemain pour toucher plus de monde."}]'::jsonb,
   'A', 'Le formateur prend cet exemple de la coiffeuse : il ne s''agit pas de dire « Merci pour votre réponse » et de partir, mais de s''engager avec ceux qui répondent pour ouvrir la portée de la publication. L''algorithme donne plus de visibilité quand les gens réagissent vite, et il conseille de répondre rapidement ou de relancer avec une question.', 'Rappelez-vous ce que le formateur attend de l''auteur d''une publication engageante une fois que les internautes commencent à réagir, et comment l''algorithme en tient compte.',
   '[{"position":2,"titre":"C''est quoi un contenu qui attire ?","debut_s":388.2,"libelle":"Revoir le chapitre 2 : « C''est quoi un contenu qui attire ? » (vers 06:28)"},{"position":6,"titre":"Bâtir une communauté engagée","debut_s":145.9,"libelle":"Revoir le chapitre 6 : « Bâtir une communauté engagée » (vers 02:25)"}]'::jsonb),
  ('mod-contenus-qui-attirent-des-clients', 4, 'Q04', 'application', 'Raconter l''histoire de son business',
   'Bintou, couturière à Treichville, a ouvert son atelier après avoir perdu son emploi. Elle hésite à raconter son histoire, de peur d''exposer sa vie privée et de paraître moins professionnelle. Que lui recommanderait le formateur ?',
   '[{"id":"A","texte":"Ne montrer que ses plus belles créations, pour garder une image parfaite et sérieuse."},{"id":"B","texte":"Parler uniquement de ses tarifs et de ses délais, car c''est ce que veulent les clients."},{"id":"C","texte":"Raconter avec authenticité ce qui l''a poussée à se lancer, y compris ses difficultés."},{"id":"D","texte":"Attendre que son atelier soit devenu célèbre avant de partager son parcours."}]'::jsonb,
   'C', 'Le formateur reconnaît cette peur de s''exposer, mais encourage le storytelling : trouver son « pourquoi » (le moment qui a déclenché le parcours) et rester authentique. Ce sont les défis et les imperfections qui rendent une histoire captivante, et l''on interagit plus facilement avec des personnes qu''avec une entreprise.', 'Revoyez le pilier inspirant : ce que le formateur dit de l''histoire d''origine, de la sincérité du récit et de ce qui rapproche le public d''une marque.',
   '[{"position":2,"titre":"C''est quoi un contenu qui attire ?","debut_s":891.2,"libelle":"Revoir le chapitre 2 : « C''est quoi un contenu qui attire ? » (vers 14:51)"},{"position":2,"titre":"C''est quoi un contenu qui attire ?","debut_s":935.4,"libelle":"Revoir le chapitre 2 : « C''est quoi un contenu qui attire ? » (vers 15:35)"}]'::jsonb),
  ('mod-contenus-qui-attirent-des-clients', 5, 'Q05', 'application', 'Définir son persona',
   'Yao lance une marque de sacs en pagne. Il affirme : « Mon produit s''adresse à tout le monde » et publie des messages très généraux qui touchent peu de monde. Que doit-il faire en priorité selon le formateur ?',
   '[{"id":"A","texte":"Établir la fiche de son client idéal : problèmes, peurs, réseau préféré, objections."},{"id":"B","texte":"Publier encore plus souvent, sur tous les réseaux, pour toucher le plus de monde possible."},{"id":"C","texte":"Booster chacune de ses publications pour qu''elles atteignent davantage d''abonnés."},{"id":"D","texte":"Élargir sa gamme de produits afin de plaire à toutes les catégories de clients."}]'::jsonb,
   'A', 'Le formateur explique que vouloir parler à tout le monde produit des messages trop larges et peu mémorables : sans persona, on parle à tout le monde et on ne touche personne. Le persona est une représentation fictive mais réaliste du client idéal, construite avec une fiche (âge, problème, peur, réseau préféré, objection, ce qui le ferait acheter).', 'Revoyez ce que le formateur dit des messages pensés « pour tout le monde » et de l''outil qu''il propose pour savoir précisément à qui l''on s''adresse.',
   '[{"position":3,"titre":"Comprendre et connaître son audience","debut_s":67.2,"libelle":"Revoir le chapitre 3 : « Comprendre et connaître son audience » (vers 01:07)"},{"position":3,"titre":"Comprendre et connaître son audience","debut_s":55.9,"libelle":"Revoir le chapitre 3 : « Comprendre et connaître son audience » (vers 00:55)"}]'::jsonb),
  ('mod-contenus-qui-attirent-des-clients', 6, 'Q06', 'application', 'Structurer un post qui convertit',
   'Mariam livre des plats de garba au Plateau. Laquelle de ces publications respecte la structure d''un bon post présentée par le formateur ?',
   '[{"id":"A","texte":"« Mariam Garba, le meilleur garba du Plateau depuis 2019. Qualité et hygiène garanties. Appelez-nous, écrivez-nous ou passez à la boutique ! »"},{"id":"B","texte":"« Vous avez faim à midi ? Notre garba est délicieux, copieux et préparé chaque matin avec soin. Bon appétit à tous et bonne journée au bureau ! »"},{"id":"C","texte":"« Garba à 1 500 FCFA, livraison au Plateau. Commandez sur WhatsApp, appelez le numéro ci-dessous ou laissez votre adresse en commentaire. »"},{"id":"D","texte":"« Pas le temps de sortir déjeuner ? Commandez avant 11 h et recevez votre garba chaud avant 13 h. Écrivez GARBA en message privé. »"}]'::jsonb,
   'D', 'Le formateur décrit un bon post en trois étapes : une accroche qui part de la situation du client, un développement avec une preuve ou un résultat, puis un appel à l''action. Sa règle d''or : un post, un seul CTA ; sans appel à l''action, personne ne sait quoi faire. Seule la publication D réunit les trois éléments avec une action unique.', 'Reprenez les trois étapes d''un bon post et la règle d''or du formateur sur l''appel à l''action, puis vérifiez chaque publication point par point.',
   '[{"position":4,"titre":"Créer une stratégie de contenu efficace","debut_s":129,"libelle":"Revoir le chapitre 4 : « Créer une stratégie de contenu efficace » (vers 02:09)"},{"position":4,"titre":"Créer une stratégie de contenu efficace","debut_s":182.6,"libelle":"Revoir le chapitre 4 : « Créer une stratégie de contenu efficace » (vers 03:02)"},{"position":5,"titre":"Écrire des contenus qui convertissent","debut_s":34.5,"libelle":"Revoir le chapitre 5 : « Écrire des contenus qui convertissent » (vers 00:34)"}]'::jsonb),
  ('mod-contenus-qui-attirent-des-clients', 7, 'Q07', 'application', 'Planifier avec un calendrier éditorial',
   'Serge, photographe à Marcory, publie quand une idée lui vient : parfois trois posts le même jour, puis plus rien pendant deux semaines. Il manque souvent d''inspiration. Quelle méthode le formateur lui conseillerait-il ?',
   '[{"id":"A","texte":"Publier uniquement quand l''inspiration vient, pour garder des contenus spontanés."},{"id":"B","texte":"Préparer ses idées par pilier et les planifier dans un calendrier éditorial."},{"id":"C","texte":"Reprendre les tendances du moment, même sans rapport avec la photographie."},{"id":"D","texte":"Republier chaque jour la même photo promotionnelle avec ses tarifs."}]'::jsonb,
   'B', 'Le formateur explique que préparer ses idées réduit le stress et améliore la régularité : avec cinq idées par pilier, on dispose vite de 15 à 20 contenus. Le calendrier éditorial (lundi éducatif, mardi histoire, mercredi promotion…) permet de savoir quoi publier et de ne jamais manquer d''idées. Il met aussi en garde contre les tendances sans lien avec son activité.', 'Repensez à ce que le formateur recommande de faire avant même de publier pour gagner en régularité et ne plus être à court d''inspiration.',
   '[{"position":4,"titre":"Créer une stratégie de contenu efficace","debut_s":42.9,"libelle":"Revoir le chapitre 4 : « Créer une stratégie de contenu efficace » (vers 00:42)"},{"position":4,"titre":"Créer une stratégie de contenu efficace","debut_s":288.3,"libelle":"Revoir le chapitre 4 : « Créer une stratégie de contenu efficace » (vers 04:48)"}]'::jsonb),
  ('mod-contenus-qui-attirent-des-clients', 8, 'Q08', 'application', 'Transformer des abonnés en communauté',
   'Fatou vend des produits de beauté sur Facebook. Elle a 8 000 abonnés mais peu d''interactions, et ses clientes n''achètent qu''une seule fois. Que lui conseillerait le formateur pour bâtir une communauté ?',
   '[{"id":"A","texte":"Augmenter son budget publicitaire pour remplacer ses abonnés inactifs par de nouveaux."},{"id":"B","texte":"Publier davantage de promotions, puisque ses abonnés connaissent déjà ses produits."},{"id":"C","texte":"Créer un rendez-vous régulier, par exemple une astuce beauté chaque jeudi."},{"id":"D","texte":"Confier sa page à quelqu''un d''autre sans plus jamais vérifier les réponses."}]'::jsonb,
   'C', 'Le formateur cite les rendez-vous réguliers parmi les moyens de bâtir une communauté : quand les gens savent qu''une astuce arrive chaque semaine, ils l''attendent, ce qui renforce l''habitude et la fidélité (son exemple des « Mercrédits »). La communauté se construit sur le long terme et rend moins dépendant de la publicité.', 'Revoyez les leviers que cite le formateur pour transformer des abonnés en communauté fidèle, et ce qui fait que des internautes prennent une habitude.',
   '[{"position":6,"titre":"Bâtir une communauté engagée","debut_s":206.9,"libelle":"Revoir le chapitre 6 : « Bâtir une communauté engagée » (vers 03:26)"},{"position":6,"titre":"Bâtir une communauté engagée","debut_s":420.6,"libelle":"Revoir le chapitre 6 : « Bâtir une communauté engagée » (vers 07:00)"}]'::jsonb),
  ('mod-contenus-qui-attirent-des-clients', 9, 'Q09', 'application', 'Choisir ses KPIs selon l''objectif',
   'Koffi, traiteur à Angré, veut générer des prospects. Son dernier post n''a obtenu que 12 likes, mais 25 personnes lui ont écrit sur WhatsApp pour demander un devis. Comment le formateur analyserait-il ce résultat ?',
   '[{"id":"A","texte":"Le post est un échec, car un bon contenu se reconnaît à son nombre de likes."},{"id":"B","texte":"Le post doit être supprimé et remplacé par un contenu plus drôle et viral."},{"id":"C","texte":"Le post est sans intérêt tant qu''il n''a pas gagné de nouveaux abonnés."},{"id":"D","texte":"Le post est réussi : pour son objectif, les messages reçus comptent plus."}]'::jsonb,
   'D', 'Le formateur souligne qu''un contenu peut générer peu de likes et pourtant être utile s''il obtient des messages, des clics ou des demandes de devis. Les indicateurs doivent correspondre à l''objectif : pour générer des prospects, on regarde les messages privés, les clics sur WhatsApp et les demandes de devis.', 'Demandez-vous d''abord quel est l''objectif de Koffi, puis quels indicateurs le formateur associe précisément à cet objectif-là.',
   '[{"position":7,"titre":"Bonus : KPIs et publicité","debut_s":37.8,"libelle":"Revoir le chapitre 7 : « Bonus : KPIs et publicité » (vers 00:37)"},{"position":7,"titre":"Bonus : KPIs et publicité","debut_s":48.4,"libelle":"Revoir le chapitre 7 : « Bonus : KPIs et publicité » (vers 00:48)"}]'::jsonb),
  ('mod-contenus-qui-attirent-des-clients', 10, 'Q10', 'application', 'Utiliser la publicité à bon escient',
   'Aya vend des bijoux à Bingerville. Une de ses publications n''a eu presque aucune réaction ; elle veut la booster avec 500 FCFA pour « la sauver ». Selon le formateur, quelle est la bonne démarche ?',
   '[{"id":"A","texte":"Choisir un post qui a déjà bien marché, puis fixer objectif, ciblage et budget suffisant."},{"id":"B","texte":"Booster ce post sans attendre, car la publicité sert justement à rattraper un contenu faible."},{"id":"C","texte":"Garder ce post et le booster plusieurs fois avec 500 FCFA jusqu''à ce qu''il finisse par décoller."},{"id":"D","texte":"Ne jamais faire de publicité, car un bon contenu finit toujours par être vu par tout le monde."}]'::jsonb,
   'A', 'Pour le formateur, « la pub amplifie ce qui marche, elle ne répare pas ce qui est cassé ». Avant de booster, on prend un post qui a déjà bien marché (likes, commentaires), on définit l''objectif, on cible les bonnes personnes et on met un vrai budget, pas une somme symbolique. Il rappelle aussi qu''un excellent contenu que personne ne voit ne sert à rien.', 'Rappelez-vous la phrase du formateur sur ce que la publicité peut et ne peut pas faire, et les étapes qu''il décrit avant de lancer un boost.',
   '[{"position":7,"titre":"Bonus : KPIs et publicité","debut_s":168.7,"libelle":"Revoir le chapitre 7 : « Bonus : KPIs et publicité » (vers 02:48)"},{"position":7,"titre":"Bonus : KPIs et publicité","debut_s":141.7,"libelle":"Revoir le chapitre 7 : « Bonus : KPIs et publicité » (vers 02:21)"}]'::jsonb);

-- ENT_M10 → mod-transformer-tiktok-en-machine-dacquisition-client
insert into quiz (module_id, code, version, seuil_reussite, tentatives_par_jour)
values ('mod-transformer-tiktok-en-machine-dacquisition-client', 'ENT_M10', 'v1', 100, 3)
on conflict (module_id) do update
  set code = excluded.code, version = excluded.version,
      seuil_reussite = excluded.seuil_reussite, tentatives_par_jour = excluded.tentatives_par_jour;
delete from quiz_questions where module_id = 'mod-transformer-tiktok-en-machine-dacquisition-client';
insert into quiz_questions
  (module_id, position, code, niveau, competence, enonce, options, bonne_reponse, justification, piste_si_erreur, renvois)
values
  ('mod-transformer-tiktok-en-machine-dacquisition-client', 1, 'Q01', 'compréhension', 'Comprendre le tunnel de vente',
   'Au sens où le formateur définit le tunnel de vente sur TikTok, laquelle de ces descriptions correspond à un tunnel de vente ?',
   '[{"id":"A","texte":"L''ensemble des vidéos publiées sur un compte au cours d''un mois, classées par nombre de vues."},{"id":"B","texte":"Le parcours d''un inconnu qui voit une vidéo, visite le profil, clique et achète."},{"id":"C","texte":"La liste des abonnés d''un compte qui ont déjà commandé au moins une fois un produit."},{"id":"D","texte":"Le budget publicitaire dépensé pour faire apparaître ses vidéos dans le fil « Pour toi »."}]'::jsonb,
   'B', 'Pour le formateur, le tunnel de vente est le chemin suivi par quelqu''un qui ne vous connaissait pas jusqu''au moment où il achète : il tombe sur une vidéo, suit le profil, voit le lien de commande, arrive sur WhatsApp et la vente se conclut. Ce parcours doit être clair et bien rodé pour transformer les vues en commandes.', 'Le tunnel de vente n''est ni une liste ni un budget : repensez aux étapes que franchit une personne entre le moment où elle ne vous connaît pas et le moment où elle devient cliente.',
   '[{"position":2,"titre":"Définitions","debut_s":70.4,"libelle":"Revoir le chapitre 2 : « Définitions » (vers 01:10)"}]'::jsonb),
  ('mod-transformer-tiktok-en-machine-dacquisition-client', 2, 'Q02', 'application', 'Bâtir ses contenus à partir de la cible',
   'Adjoua vend des vêtements et accessoires pour bébés à Cocody. Elle ne sait pas quelles vidéos publier sur TikTok. Selon le formateur, comment doit-elle choisir ses sujets ?',
   '[{"id":"A","texte":"Partir des questions que se posent les futures et jeunes mamans, et y répondre en vidéo."},{"id":"B","texte":"Reprendre les tendances du moment pour toucher le plus grand nombre de personnes possible."},{"id":"C","texte":"Présenter chaque jour un nouvel article avec son prix, sans autre type de contenu."},{"id":"D","texte":"Copier les sujets des comptes les plus suivis d''Abidjan, quel que soit leur domaine."}]'::jsonb,
   'A', 'Le formateur rappelle qu''on fait du contenu pour attirer certaines personnes, pas tout le monde. Avec l''exemple des vêtements pour bébés, il explique qu''il suffit de répondre aux questions que se pose la cible (biberons, lit démontable, jouets) : plus on y répond, plus on attire son attention, et plus il devient facile de la convertir en clientes.', 'Demandez-vous qui Adjoua cherche réellement à attirer, et ce que ces personnes ont dans la tête avant d''acheter ; le formateur place cette personne au cœur de la réflexion.',
   '[{"position":3,"titre":"Stratégie de contenu : cible et calendrier","debut_s":95.1,"libelle":"Revoir le chapitre 3 : « Stratégie de contenu : cible et calendrier » (vers 01:35)"}]'::jsonb),
  ('mod-transformer-tiktok-en-machine-dacquisition-client', 3, 'Q03', 'application', 'Combiner les trois types de contenus',
   'Konan publie chaque jour des sketchs drôles sur TikTok. Il atteint 50 000 vues et 10 000 abonnés, mais ne vend aucune de ses montres. D''après le formateur, que doit-il changer ?',
   '[{"id":"A","texte":"Publier encore plus de sketchs, car les ventes finissent toujours par suivre les vues."},{"id":"B","texte":"Faire une semaine d''interaction, puis une semaine d''expertise, puis une semaine de vente."},{"id":"C","texte":"Publier chaque jour un contenu d''interaction, un d''expertise et un de vente."},{"id":"D","texte":"Arrêter les sketchs et ne publier désormais que des vidéos de vente avec le prix."}]'::jsonb,
   'C', 'Le formateur cite ce cas : si l''on ne fait que des contenus d''interaction, on aura des vues et des abonnés mais aucune vente. Il faut combiner les trois types de contenus, tous les jours et non par semaine : l''interaction donne la visibilité, l''expertise convainc et la vente pousse à acheter.', 'Rappelez-vous le rôle de chaque type de contenu présenté par le formateur, et le rythme auquel il recommande de les publier.',
   '[{"position":3,"titre":"Stratégie de contenu : cible et calendrier","debut_s":403.8,"libelle":"Revoir le chapitre 3 : « Stratégie de contenu : cible et calendrier » (vers 06:43)"},{"position":3,"titre":"Stratégie de contenu : cible et calendrier","debut_s":417.2,"libelle":"Revoir le chapitre 3 : « Stratégie de contenu : cible et calendrier » (vers 06:57)"}]'::jsonb),
  ('mod-transformer-tiktok-en-machine-dacquisition-client', 4, 'Q04', 'application', 'Fixer un rythme de publication tenable',
   'Mariam démarre sur TikTok pour vendre ses savons au karité. Motivée, elle veut publier dix vidéos par jour dès la première semaine. Que lui conseillerait le formateur ?',
   '[{"id":"A","texte":"Garder ce rythme de dix vidéos, car plus on publie tôt, plus l''algorithme récompense."},{"id":"B","texte":"Publier une seule vidéo par semaine, mais sans jamais manquer un rendez-vous."},{"id":"C","texte":"Publier seulement les jours où elle a une bonne idée, pour garder une bonne qualité."},{"id":"D","texte":"Commencer à une ou trois vidéos par jour, puis augmenter progressivement son rythme."}]'::jsonb,
   'D', 'Le formateur demande un calendrier réaliste : une à trois vidéos par jour suffisent pour commencer. Démarrer à dix pour ne plus suivre ensuite rend le compte « pas fiable » aux yeux de l''algorithme. Une vidéo par semaine serait régulière mais pas assez fréquente pour rester présent dans l''esprit des gens.', 'Pensez à ce qui se passe lorsqu''on démarre plus fort qu''on ne peut tenir, et à la différence que fait le formateur entre être régulier et être fréquent.',
   '[{"position":3,"titre":"Stratégie de contenu : cible et calendrier","debut_s":451.3,"libelle":"Revoir le chapitre 3 : « Stratégie de contenu : cible et calendrier » (vers 07:31)"},{"position":3,"titre":"Stratégie de contenu : cible et calendrier","debut_s":526.1,"libelle":"Revoir le chapitre 3 : « Stratégie de contenu : cible et calendrier » (vers 08:46)"}]'::jsonb),
  ('mod-transformer-tiktok-en-machine-dacquisition-client', 5, 'Q05', 'application', 'Organiser sa création de contenu',
   'Chaque matin, Yao se demande quelle vidéo tourner pour son restaurant de Marcory. Les jours chargés, il ne publie rien. Selon le formateur, comment doit-il s''organiser ?',
   '[{"id":"A","texte":"Continuer à créer chaque matin, mais se lever plus tôt pour avoir le temps de filmer."},{"id":"B","texte":"Tourner de nombreuses vidéos d''avance en une séance, puis les publier au fil des jours."},{"id":"C","texte":"Ne publier que le week-end, quand il a plus de temps libre pour bien préparer ses vidéos."},{"id":"D","texte":"Attendre d''avoir une idée vraiment originale avant de filmer, même s''il saute des jours."}]'::jsonb,
   'B', 'Le formateur a vécu ce problème : créer chaque jour fait rater des publications les jours compliqués. Sa solution est d''avoir des séances de création de contenu (par exemple 28 contenus pour deux semaines), puis de simplement publier ; un contenu supplémentaire peut s''ajouter pour suivre une tendance ou partager un témoignage.', 'Repensez à l''expérience racontée par le formateur à ses débuts, et à la façon dont son agence produit aujourd''hui ses contenus pour rester présente même les jours compliqués.',
   '[{"position":3,"titre":"Stratégie de contenu : cible et calendrier","debut_s":750,"libelle":"Revoir le chapitre 3 : « Stratégie de contenu : cible et calendrier » (vers 12:30)"}]'::jsonb),
  ('mod-transformer-tiktok-en-machine-dacquisition-client', 6, 'Q06', 'application', 'Formuler un appel à l''action',
   'Aminata vend des parfums à Yopougon. Sa vidéo présente trois parfums en promotion, puis s''arrête sans autre message. Comment devrait-elle la terminer, selon le formateur ?',
   '[{"id":"A","texte":"Ne rien ajouter : les spectateurs intéressés savent déjà qu''ils peuvent la contacter."},{"id":"B","texte":"Coller le lien de sa boutique dans la légende de la vidéo pour qu''on clique dessus."},{"id":"C","texte":"Donner une consigne claire et simple, comme écrire « prix » en commentaire."},{"id":"D","texte":"Laisser chaque spectateur choisir lui-même ce qu''il souhaite faire après la vidéo."}]'::jsonb,
   'C', 'Pour le formateur, une vidéo doit se terminer avec clairement quelque chose à faire : si l''on ne dit rien, l''utilisateur doit décider, et il ne fait rien. L''appel à l''action doit être clair, visible, simple et répété (« Écrivez en commentaire “prix” », « Le lien pour commander est dans ma bio »). Il précise aussi qu''on ne peut pas mettre de lien dans la légende sur TikTok.', 'Le formateur compare les utilisateurs à des enfants qui attendent qu''on leur dise quoi faire : demandez-vous ce qui arrive quand on les laisse décider, et où un lien peut être placé sur TikTok.',
   '[{"position":3,"titre":"Stratégie de contenu : cible et calendrier","debut_s":1094.5,"libelle":"Revoir le chapitre 3 : « Stratégie de contenu : cible et calendrier » (vers 18:14)"}]'::jsonb),
  ('mod-transformer-tiktok-en-machine-dacquisition-client', 7, 'Q07', 'application', 'Animer un live sans attendre le public',
   'Bintou lance un live annoncé pour présenter ses pagnes. Au bout d''une minute, seules deux personnes sont connectées. Que doit-elle faire, d''après le formateur ?',
   '[{"id":"A","texte":"Démarrer tout de suite sa présentation comme devant des milliers de personnes."},{"id":"B","texte":"Attendre en silence d''avoir au moins dix spectateurs avant de commencer à présenter."},{"id":"C","texte":"Arrêter le live et le relancer plus tard, quand davantage de personnes seront en ligne."},{"id":"D","texte":"Discuter de tout et de rien avec les deux personnes en attendant que d''autres arrivent."}]'::jsonb,
   'A', 'Le formateur met en garde contre l''erreur d''attendre un certain nombre de spectateurs : ceux qui sont là attendent puis repartent. Il faut ignorer le nombre de spectateurs et délivrer comme devant des milliers de personnes ; c''est en délivrant que les gens partagent, recommandent et que le live se remplit.', 'Demandez-vous ce que font les premiers spectateurs pendant qu''on les fait patienter, et ce qui, selon le formateur, fait réellement grossir l''audience d''un live.',
   '[{"position":4,"titre":"Transformer les vues en clients","debut_s":263.5,"libelle":"Revoir le chapitre 4 : « Transformer les vues en clients » (vers 04:23)"}]'::jsonb),
  ('mod-transformer-tiktok-en-machine-dacquisition-client', 8, 'Q08', 'application', 'Répéter les informations clés en live',
   'Pendant un live d''une heure, Serge annonce dès le début le prix de ses chaussures (25 000 FCFA) et son numéro WhatsApp. Il n''y revient plus ensuite. Quelle erreur commet-il ?',
   '[{"id":"A","texte":"Aucune : l''information est donnée une fois, chacun peut la retrouver dans la rediffusion."},{"id":"B","texte":"Il aurait dû garder le prix pour la toute fin, afin de maintenir le suspense jusqu''au bout."},{"id":"C","texte":"Il aurait dû donner son numéro uniquement en message privé, pour éviter les curieux."},{"id":"D","texte":"Il oublie que les spectateurs changent sans cesse : prix et contact sont à répéter."}]'::jsonb,
   'D', 'Le formateur explique que, dans un live, les gens viennent et partent : ceux qui regardent à un moment T ne sont pas les mêmes à T + 1. Le prix, le contact et les éléments importants du produit doivent donc être répétés, et il faut expliquer comment passer commande, sinon le live a beaucoup d''interactions mais aucune vente.', 'Pensez à la façon dont le public d''un live évolue au fil des minutes, et à ce dont a besoin une personne qui arrive au milieu pour pouvoir acheter.',
   '[{"position":4,"titre":"Transformer les vues en clients","debut_s":308.1,"libelle":"Revoir le chapitre 4 : « Transformer les vues en clients » (vers 05:08)"},{"position":4,"titre":"Transformer les vues en clients","debut_s":327.5,"libelle":"Revoir le chapitre 4 : « Transformer les vues en clients » (vers 05:27)"}]'::jsonb),
  ('mod-transformer-tiktok-en-machine-dacquisition-client', 9, 'Q09', 'application', 'Juger une vidéo sur sa capacité à vendre',
   'Fatou compare deux vidéos : la première a 40 000 vues et aucun message ; la seconde a 3 000 vues et 25 messages WhatsApp demandant le prix. Que conclurait le formateur ?',
   '[{"id":"A","texte":"La première est la meilleure : il faut refaire des vidéos qui génèrent autant de vues."},{"id":"B","texte":"Ces chiffres ne veulent rien dire : mieux vaut imiter ce que font les vendeurs à succès."},{"id":"C","texte":"La seconde déclenche l''achat : il faut analyser ce qui a fonctionné pour le reproduire."},{"id":"D","texte":"Les deux se valent : seul compte le nombre total d''abonnés gagnés sur la semaine."}]'::jsonb,
   'C', 'Le formateur explique que les messages reçus et les demandes de prix montrent si une vidéo arrive à déclencher l''achat : une vidéo qui pousse les gens à vous contacter est une bonne vidéo. Il faut alors analyser ce qu''on y a fait (offre, manière, appel à l''action) pour le refaire, au lieu de rester attaché aux seules vues ou de changer de stratégie en copiant les autres.', 'Le formateur met en garde contre l''attachement aux seules vues : demandez-vous quel indicateur montre qu''une vidéo pousse les gens à acheter, et ce qu''il faut faire d''une vidéo qui y parvient.',
   '[{"position":5,"titre":"Lire ses statistiques","debut_s":30.3,"libelle":"Revoir le chapitre 5 : « Lire ses statistiques » (vers 00:30)"},{"position":4,"titre":"Transformer les vues en clients","debut_s":661.9,"libelle":"Revoir le chapitre 4 : « Transformer les vues en clients » (vers 11:01)"}]'::jsonb),
  ('mod-transformer-tiktok-en-machine-dacquisition-client', 10, 'Q10', 'application', 'Exploiter la durée de visionnage',
   'Les statistiques de Kouadio montrent que, sur ses vidéos de pâtisserie, la plupart des spectateurs décrochent vers la 15e seconde. Selon le formateur, que doit-il faire ?',
   '[{"id":"A","texte":"Republier exactement les mêmes vidéos à une autre heure, pour toucher un autre public."},{"id":"B","texte":"Revoir ses vidéos vers la 15e seconde, repérer ce qui fait décrocher et le corriger."},{"id":"C","texte":"Ignorer ce chiffre, car seul le nombre total de vues permet de juger une vidéo."},{"id":"D","texte":"Changer complètement de style en imitant la dernière vidéo virale qu''il a vue."}]'::jsonb,
   'B', 'Le formateur explique que la durée moyenne de visionnage indique à quel moment on perd l''attention des gens. Quand les spectateurs décrochent à 15 secondes, il faut retourner voir ce qui se passe à ce moment de la vidéo et le corriger dans la suivante : c''est en analysant ses données qu''on construit des vidéos plus efficaces.', 'Demandez-vous ce que cet indicateur révèle sur la capacité de la vidéo à retenir l''attention, et comment le formateur propose de s''en servir pour la prochaine vidéo.',
   '[{"position":4,"titre":"Transformer les vues en clients","debut_s":626.9,"libelle":"Revoir le chapitre 4 : « Transformer les vues en clients » (vers 10:26)"},{"position":5,"titre":"Lire ses statistiques","debut_s":31.1,"libelle":"Revoir le chapitre 5 : « Lire ses statistiques » (vers 00:31)"}]'::jsonb);

-- SM_M05 → mod-accroches-qui-stoppent-le-scroll-et-ia-copywriting
insert into quiz (module_id, code, version, seuil_reussite, tentatives_par_jour)
values ('mod-accroches-qui-stoppent-le-scroll-et-ia-copywriting', 'SM_M05', 'v1', 100, 3)
on conflict (module_id) do update
  set code = excluded.code, version = excluded.version,
      seuil_reussite = excluded.seuil_reussite, tentatives_par_jour = excluded.tentatives_par_jour;
delete from quiz_questions where module_id = 'mod-accroches-qui-stoppent-le-scroll-et-ia-copywriting';
insert into quiz_questions
  (module_id, position, code, niveau, competence, enonce, options, bonne_reponse, justification, piste_si_erreur, renvois)
values
  ('mod-accroches-qui-stoppent-le-scroll-et-ia-copywriting', 1, 'Q01', 'application', 'Comprendre la concurrence pour l''attention',
   'Adjoua tient une pâtisserie à Cocody. Elle pense que ses publications ne sont en concurrence qu''avec celles des autres pâtisseries d''Abidjan. Selon le formateur, que doit-elle comprendre ?',
   '[{"id":"A","texte":"Elle doit surtout surveiller les prix et les promotions des pâtisseries voisines."},{"id":"B","texte":"Son contenu affronte aussi WhatsApp, l''humour, l''actualité et les notifications."},{"id":"C","texte":"Elle n''a aucune concurrence si ses gâteaux sont plus beaux que les autres."},{"id":"D","texte":"Elle doit publier plus souvent que ses concurrents pour rester visible."}]'::jsonb,
   'B', 'Le formateur rappelle que nous vivons dans un monde de l''attention : un contenu n''est pas seulement en concurrence avec les concurrents directs, mais aussi avec les messages WhatsApp, les vidéos humoristiques, l''actualité et les notifications. L''accroche doit donc interrompre ce réflexe de défilement.', 'Pensez à tout ce qui défile sur le téléphone d''une cliente en même temps que la publication d''Adjoua, et pas seulement aux autres commerces.',
   '[{"position":1,"titre":"Introduction","debut_s":65.4,"libelle":"Revoir le chapitre 1 : « Introduction » (vers 01:05)"}]'::jsonb),
  ('mod-accroches-qui-stoppent-le-scroll-et-ia-copywriting', 2, 'Q02', 'compréhension', 'Définir le rôle d''une accroche',
   'Un vendeur de chaussures à Treichville pense que la première phrase de sa vidéo sert à présenter son entreprise. D''après la définition du formateur, quel est le rôle d''une accroche ?',
   '[{"id":"A","texte":"Présenter l''histoire et les valeurs de l''entreprise dès la première phrase."},{"id":"B","texte":"Donner tout de suite le prix et l''adresse pour gagner du temps."},{"id":"C","texte":"Montrer le logo de la boutique pour que les clients le mémorisent."},{"id":"D","texte":"Susciter la curiosité ou surprendre pour retenir la personne qui défile."}]'::jsonb,
   'D', 'Pour le formateur, l''accroche (ou hook) est l''élément destiné à capter l''attention dès les premières secondes. Son rôle est de susciter la curiosité, de surprendre ou de poser une question pour empêcher l''utilisateur de passer au contenu suivant, ce qui augmente le taux de rétention.', 'Rappelez-vous ce qui se joue pendant les trois premières secondes d''une vidéo et ce que l''accroche doit empêcher l''utilisateur de faire.',
   '[{"position":2,"titre":"Définitions","debut_s":71.9,"libelle":"Revoir le chapitre 2 : « Définitions » (vers 01:11)"}]'::jsonb),
  ('mod-accroches-qui-stoppent-le-scroll-et-ia-copywriting', 3, 'Q03', 'application', 'Appliquer la formule d''une accroche efficace',
   'Une pâtisserie d''Abidjan qui livre des gâteaux d''anniversaire veut une première ligne de publication Facebook. Laquelle respecte le mieux la formule clarté + pertinence + tension + cohérence ?',
   '[{"id":"A","texte":"« Votre gâteau d''anniversaire arrive en retard ? Voici comment nous livrons à l''heure. »"},{"id":"B","texte":"« Bienvenue sur la page de notre pâtisserie : découvrez toutes nos belles créations du moment. »"},{"id":"C","texte":"« Le gâteau le plus incroyable du monde vous attend : vous n''en croirez jamais vos yeux ! »"},{"id":"D","texte":"« Gâteaux, mariages, anniversaires, entreprises, livraison, devis, promotions : tout est chez nous. »"}]'::jsonb,
   'A', 'Le formateur résume une accroche efficace par la clarté (comprendre sans réfléchir), la pertinence (une cible identifiable), la tension (provoquer une réaction) et la cohérence (le contenu tient la promesse). La proposition A réunit ces quatre éléments ; les autres sont vagues, trompeuses ou veulent tout dire.', 'Vérifiez chaque phrase avec les quatre critères de la formule : le sujet est-il immédiat, la cible se reconnaît-elle, y a-t-il une réaction, et la suite pourra-t-elle tenir la promesse ?',
   '[{"position":3,"titre":"Anatomie d''une accroche qui marche","debut_s":627.7,"libelle":"Revoir le chapitre 3 : « Anatomie d''une accroche qui marche » (vers 10:27)"}]'::jsonb),
  ('mod-accroches-qui-stoppent-le-scroll-et-ia-copywriting', 4, 'Q04', 'application', 'Distinguer accroche et clickbait',
   'Ibrahim vend des accessoires de téléphone à Adjamé. Sa vidéo commence par « Je vous offre un iPhone gratuitement », puis présente seulement ses coques. Les vues montent, mais les gens partent vite. Selon le formateur, quel est le problème ?',
   '[{"id":"A","texte":"Sa vidéo est beaucoup trop longue : il doit la couper à quinze secondes."},{"id":"B","texte":"Ses coques ne plaisent pas : il doit changer de produit."},{"id":"C","texte":"Son accroche promet ce que la suite ne donne pas : c''est du clickbait."},{"id":"D","texte":"Il ne publie pas assez : il doit poster plusieurs fois par jour."}]'::jsonb,
   'C', 'Le formateur insiste : une accroche n''est pas du clickbait, elle attire la bonne personne vers le bon message. Si la suite ne correspond pas à ce qui est annoncé, les personnes quittent le contenu et cela donne une mauvaise image. Le contenu doit tenir la promesse faite par l''ouverture.', 'Comparez ce qu''annonce la première phrase d''Ibrahim avec ce que la vidéo montre ensuite, et repensez au critère de cohérence.',
   '[{"position":3,"titre":"Anatomie d''une accroche qui marche","debut_s":272.6,"libelle":"Revoir le chapitre 3 : « Anatomie d''une accroche qui marche » (vers 04:32)"},{"position":3,"titre":"Anatomie d''une accroche qui marche","debut_s":844.9,"libelle":"Revoir le chapitre 3 : « Anatomie d''une accroche qui marche » (vers 14:04)"}]'::jsonb),
  ('mod-accroches-qui-stoppent-le-scroll-et-ia-copywriting', 5, 'Q05', 'application', 'Prévoir l''appel à l''action',
   'Awa vend de l''attiéké à Yopougon. Sa vidéo commence par une histoire personnelle qui accroche bien et fait beaucoup de vues, mais elle se termine sans rien demander. Personne ne commande. Que lui conseillerait le formateur ?',
   '[{"id":"A","texte":"Changer d''accroche, car une histoire personnelle ne fait pas vendre."},{"id":"B","texte":"Finir chaque vidéo en disant clairement quoi faire : écrire sur WhatsApp."},{"id":"C","texte":"Publier la même vidéo plusieurs fois pour toucher plus de monde."},{"id":"D","texte":"Retirer l''histoire et montrer directement le plat dès la première seconde."}]'::jsonb,
   'B', 'Le formateur rappelle qu''à la fin d''un contenu, il faut toujours un appel à l''action dit clairement : s''abonner, cliquer, appeler ou écrire sur WhatsApp. Sinon, c''est de l''énergie dépensée pour rien : la personne satisfaite passe à la suite sans agir.', 'L''accroche d''Awa fonctionne : demandez-vous ce qui manque à la fin de sa vidéo pour transformer l''attention en commande.',
   '[{"position":3,"titre":"Anatomie d''une accroche qui marche","debut_s":1004.2,"libelle":"Revoir le chapitre 3 : « Anatomie d''une accroche qui marche » (vers 16:44)"}]'::jsonb),
  ('mod-accroches-qui-stoppent-le-scroll-et-ia-copywriting', 6, 'Q06', 'application', 'Soigner la première ligne visible',
   'Une coach d''Abidjan publie de longs textes sur Facebook pour les commerçantes. Sa première ligne, avant « voir plus », est : « Bonjour à tous, j''espère que vous allez bien ce lundi. » Que lui recommanderait le formateur ?',
   '[{"id":"A","texte":"Garder cette salutation, car la politesse donne envie de lire la suite."},{"id":"B","texte":"Raccourcir le texte entier pour qu''il n''y ait plus de bouton « voir plus »."},{"id":"C","texte":"Ajouter beaucoup d''émojis pour rendre la première ligne plus visible."},{"id":"D","texte":"Ouvrir sur une phrase où les commerçantes se reconnaissent tout de suite."}]'::jsonb,
   'D', 'Le formateur demande d''accorder une attention particulière à la première ligne visible avant le « voir plus » : si elle n''attire pas la personne visée, celle-ci ne clique pas. La pertinence et l''identification exigent que la cible se reconnaisse immédiatement (« Si tu es entrepreneur et que tu galères… »).', 'Demandez-vous ce qui pousse une lectrice à cliquer sur « voir plus », et repensez à l''élément d''identification parmi ceux qui renforcent une accroche.',
   '[{"position":3,"titre":"Anatomie d''une accroche qui marche","debut_s":734.4,"libelle":"Revoir le chapitre 3 : « Anatomie d''une accroche qui marche » (vers 12:14)"},{"position":3,"titre":"Anatomie d''une accroche qui marche","debut_s":542.5,"libelle":"Revoir le chapitre 3 : « Anatomie d''une accroche qui marche » (vers 09:02)"}]'::jsonb),
  ('mod-accroches-qui-stoppent-le-scroll-et-ia-copywriting', 7, 'Q07', 'application', 'Rédiger un prompt avec la méthode CRAFT',
   'Aminata vend des pagnes tissés à Bouaké. Elle écrit à l''IA : « Donne-moi des accroches pour vendre mes pagnes. » Les réponses sont génériques. Quelle amélioration suit la méthode CRAFT du formateur ?',
   '[{"id":"A","texte":"Préciser son activité et sa cible, le rôle de l''IA, la tâche, le format et le ton."},{"id":"B","texte":"Ajouter « sois très créatif » et laisser l''IA décider de tout le reste."},{"id":"C","texte":"Raccourcir encore le prompt pour laisser plus de liberté à l''IA."},{"id":"D","texte":"Poser la même question à plusieurs IA et garder simplement la réponse la plus longue."}]'::jsonb,
