-- Contrôle : un quiz complet par module importé, sinon tout est annulé.
do $$
begin
  if exists (select 1 from quiz z where z.module_id in ('mod-trouver-ses-premiers-clients', 'mod-vendre-sans-site-web-whatsapp-business', 'mod-contenus-qui-attirent-des-clients', 'mod-transformer-tiktok-en-machine-dacquisition-client', 'mod-accroches-qui-stoppent-le-scroll-et-ia-copywriting')
             and (select count(*) from quiz_questions q where q.module_id = z.module_id) <> 10) then
    raise exception 'Quiz incomplet après import';
  end if;
end;
$$;

